 40→  function element(tagName, className, text) {
 41→    var node = document.createElement(tagName);
 42→    if (className) {
 43→      node.className = className;
 44→    }
 45→    if (text !== undefined && text !== null) {
 46→      node.textContent = String(text);
 47→    }
 48→    return node;
 49→  }
