 51→  function displayValue(value) {
 52→    if (value === null || value === undefined) {
 53→      return "Not present in file";
 54→    }
 55→    if (typeof value === "object") {
 56→      return JSON.stringify(value);
 57→    }
 58→    return String(value);
 59→  }
