 61→  function humanizeKey(key) {
 62→    return String(key)
 63→      .replace(/([a-z])([A-Z])/g, "$1 $2")
 64→      .replace(/[_-]+/g, " ")
 65→      .replace(/\s+/g, " ")
 66→      .trim()
 67→      .replace(/^\w/, function (letter) { return letter.toUpperCase(); });
 68→  }
