 70→  function formatNumber(value, path) {
 71→    if (typeof value !== "number" || !isFinite(value)) {
 72→      return displayValue(value);
 73→    }
 74→    var name = String(path).split(".").pop();
 75→    if (/_sgd$|amount_sgd$|price_sgd$|fare_sgd$|delta_sgd$/.test(name)) {
 76→      return "SGD " + value.toFixed(2);
 77→    }
 78→    if (/_pct$/.test(name)) {
 79→      return value.toFixed(2).replace(/\.00$/, "") + "%";
 80→    }
 81→    if (/_km$/.test(name)) {
 82→      return value + " km";
 83→    }
 84→    if (/_minutes?$/.test(name)) {
 85→      return value + " min";
 86→    }
 87→    if (/_m$/.test(name)) {
 88→      return value + " m";
 89→    }
 90→    if (name === "rating" || name === "surge_multiplier") {
 91→      return value.toFixed(2);
 92→    }
 93→    return String(value);
 94→  }
 95→
 96→  function formatEvidenceValue(value, path) {
 97→    if (value === null || value === undefined) {
 98→      return "NULL";
 99→    }
100→    if (typeof value === "number") {
101→      return formatNumber(value, path);
102→    }
103→    if (typeof value === "boolean") {
104→      return value ? "Yes" : "No";
105→    }
106→    if (Array.isArray(value)) {
107→      return value.map(function (item) { return displayValue(item); }).join(", ");
108→    }
109→    return String(value);
110→  }
