143→  function attachRunFiles(files) {
144→    state.payloadFiles = {};
145→    var attached = 0;
146→    Array.prototype.forEach.call(files || [], function (file) {
147→      var relative = normalizedPayloadRef(relativeRunPath(file));
148→      if (relative) {
149→        state.payloadFiles[relative] = file;
150→        attached += 1;
151→      }
152→    });
153→    if (attached > 0) {
154→      setPayloadStatus("Attached " + attached + " run file(s); event payloads can be opened.", "success");
155→    } else {
156→      setPayloadStatus("No run files were attached.", "error");
157→    }
158→    if (state.caseFile) {
159→      renderEvents(state.caseFile);
160→    }
161→  }
