241→  function noteValues(context, pack) {
242→    if (context && Array.isArray(context.notes) && context.notes.length > 0) {
243→      return context.notes;
244→    }
245→    if (pack && Array.isArray(pack.notes) && pack.notes.length > 0) {
246→      return pack.notes;
