330→  function renderEvidence(caseFile) {
331→    clear(evidenceContent);
332→    state.evidenceIndex = {};
333→    var pack = caseFile.evidence_pack;
334→    if (!pack || typeof pack !== "object") {
335→      var notBuilt = element("article", "deliberate-empty");
