337→      notBuilt.appendChild(element("h3", null, humanReview ? "Automated evidence not invoked" : "Evidence Pack not built"));
338→      notBuilt.appendChild(element("p", null, humanReview
339→        ? "This category was routed to human review before the Evidence Pack was built."
340→        : "This case file does not contain computed evidence."));
341→      if (!humanReview) {
342→        appendNotes(notBuilt, noteValues(null, null));
343→      }
344→      evidenceContent.appendChild(notBuilt);
345→      return;
346→    }
347→
348→    var provenance = element("dl", "evidence-provenance");
349→    ["schema_version", "trip_id", "rider_id", "driver_id", "service_type", "generated_at"].forEach(function (key) {
350→      if (Object.prototype.hasOwnProperty.call(pack, key)) {
