378→  function appendCitation(parent, reference, kind, validation) {
379→    var text = String(reference);
380→    var target = kind === "evidence" ? state.evidenceIndex[text] : state.policyIndex[text];
381→    var unknown = validation && (kind === "evidence"
382→      ? Array.isArray(validation.unknown_evidence_refs) && validation.unknown_evidence_refs.indexOf(text) !== -1
383→      : Array.isArray(validation.unknown_rule_ids) && validation.unknown_rule_ids.indexOf(text) !== -1);
384→    var citation;
385→    if (target && !unknown) {
386→      citation = element("a", "citation citation-" + kind, text);
387→      citation.href = "#" + target.id;
388→      if (kind === "evidence" && (target.value === null || target.value === undefined)) {
389→        citation.classList.add("citation-null");
390→      }
391→    } else {
392→      citation = element("span", "citation citation-unresolved", text);
393→      citation.title = "Citation could not be resolved in this case file.";
394→    }
395→    parent.appendChild(citation);
396→  }
