401→    }
402→    var block = element("div", "citation-block");
403→    block.appendChild(element("h4", "citation-title", label));
404→    var list = element("div", "citation-list");
405→    references.forEach(function (reference) {
406→      appendCitation(list, reference, kind, validation);
407→    });
408→    block.appendChild(list);
409→    parent.appendChild(block);
410→  }
