412→  function appendValidation(parent, validation) {
413→    if (!validation || typeof validation !== "object") {
414→      return;
415→    }
416→    var problems = [];
417→    ["unknown_evidence_refs", "unknown_rule_ids", "notes"].forEach(function (key) {
418→      if (Array.isArray(validation[key])) {
419→        validation[key].forEach(function (item) {
420→          problems.push(humanizeKey(key) + ": " + displayValue(item));
421→        });
422→      }
