745→  function loadEventPayload(event, panel) {
746→    if (panel.dataset.loaded === "true") {
747→      return;
748→    }
749→    panel.dataset.loaded = "true";
750→    var reference = normalizedPayloadRef(event.payload_ref);
751→    if (!reference) {
752→      panel.appendChild(element("p", "payload-unavailable", "No safe relative payload reference was supplied for this event."));
753→      return;
754→    }
755→    var file = state.payloadFiles[reference];
756→    if (!file) {
757→      panel.appendChild(element("p", "payload-unavailable", "Attach the run directory to open this payload."));
758→      return;
759→    }
760→    panel.appendChild(element("p", "payload-loading", "Reading " + reference + "…"));
761→    file.text().then(function (text) {
762→      var payload;
763→      try {
764→        payload = JSON.parse(text);
765→      } catch (error) {
766→        clear(panel);
767→        panel.appendChild(element("p", "payload-error", "This payload is not valid JSON."));
768→        return;
769→      }
770→      clear(panel);
771→      panel.appendChild(element("p", "payload-path", reference));
772→      panel.appendChild(element("pre", "payload-json", JSON.stringify(payload, null, 2)));
773→    }).catch(function () {
774→      clear(panel);
775→      panel.appendChild(element("p", "payload-error", "The payload could not be read."));
776→    });
777→  }
