779→  function renderEvents(caseFile) {
780→    clear(eventsContent);
781→    var events = Array.isArray(caseFile.events) ? caseFile.events : [];
782→    if (events.length === 0) {
783→      var empty = element("article", "deliberate-empty");
784→      empty.appendChild(element("h3", null, "No event traffic in this case file"));
785→      empty.appendChild(element("p", null, "The case file did not contain an events array."));
786→      eventsContent.appendChild(empty);
787→      return;
788→    }
789→    var intro = element("p", "event-intro", "Agent-to-agent traffic is shown in sequence. Expand an event to inspect its payload.");
790→    eventsContent.appendChild(intro);
791→    var stream = element("div", "event-stream");
792→    events.forEach(function (event, index) {
793→      if (!event || typeof event !== "object" || Array.isArray(event)) {
794→        var malformed = element("div", "event-row event-malformed");
795→        malformed.appendChild(element("p", null, "Event row " + (index + 1) + " is malformed and cannot be shown."));
796→        stream.appendChild(malformed);
797→        return;
798→      }
799→      var details = element("details", "event-row");
800→      details.dataset.sequence = displayValue(event.seq);
801→      if (event.type === "judge.ruling_withheld") {
802→        details.classList.add("event-internal");
803→      }
804→      var summary = element("summary", "event-summary");
805→      summary.appendChild(element("span", "event-seq", "#" + displayValue(event.seq)));
806→      summary.appendChild(element("time", "event-time", displayValue(event.ts)));
807→      summary.appendChild(element("span", "event-type", displayValue(event.type)));
808→      var route = element("span", "event-route");
809→      route.appendChild(element("span", "event-actor", displayValue(event.from)));
810→      route.appendChild(element("span", "event-arrow", "→"));
811→      route.appendChild(element("span", "event-actor", displayValue(event.to)));
812→      summary.appendChild(route);
813→      summary.appendChild(element("span", "event-summary-text", displayValue(event.summary)));
814→      summary.appendChild(element("span", "event-payload-ref", normalizedPayloadRef(event.payload_ref) || "No payload reference"));
815→      details.appendChild(summary);
816→      var panel = element("div", "event-payload");
817→      details.appendChild(panel);
818→      details.addEventListener("toggle", function () {
819→        if (details.open) {
820→          loadEventPayload(event, panel);
821→        }
822→      });
823→      stream.appendChild(details);
824→    });
825→    eventsContent.appendChild(stream);
826→  }
