828→  function renderCase(fileName, caseFile) {
829→    state.caseFile = caseFile;
830→    loadedFile.textContent = fileName;
831→    renderMetadata(caseFile);
832→    renderGrievance(caseFile);
833→    renderEvidence(caseFile);
834→    renderClaims(caseFile);
835→    renderResolution(caseFile);
836→    renderEvents(caseFile);
837→    workspace.hidden = false;
838→    setStatus("Loaded " + fileName + ".", "success");
839→  }
