841→  function handleFile(file) {
842→    if (!file) {
843→      return;
844→    }
845→
846→    state.payloadFiles = {};
847→    setPayloadStatus("Payload files are not attached.", "idle");
848→    setStatus("Reading " + file.name + "…", "loading");
849→    file.text().then(function (text) {
850→      var parsed;
851→      try {
852→        parsed = JSON.parse(text);
853→      } catch (error) {
854→        throw new Error("The selected file is not valid JSON.");
855→      }
856→      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
857→        throw new Error("The selected JSON must contain one case-file object.");
858→      }
859→      renderCase(file.name, parsed);
860→    }).catch(function (error) {
861→      workspace.hidden = true;
862→      clear(metadataList);
863→      clear(grievanceContent);
864→      clear(evidenceContent);
865→      clear(claimsContent);
866→      clear(policyContent);
867→      clear(resolutionContent);
868→      clear(eventsContent);
869→      setStatus(error.message, "error");
870→    });
871→  }
